var e=[{additionText:`Na googlu mamy same dobre opinie.`,title:`Nasza akademia czeka na ciebie.`,param:`Od lat prowadzimy kompleksowe szkolenia z dziedziny groomingu. Niesłychana wiedza oraz zaangażowanie powoduje że jesteśmy najlepsi w naszej dziedzinie. Nie ma lepszego bo tak.`,buttonText:`Zapisz się`,secondButtonAnchor:``,helpMessage:`o nas`,imageUrl:`https://picsum.photos/id/1018/1920/1080`},{title:`Kursy dla początkujących.`,additionText:`Pomagamy realizować się każdej nowej osobie`,param:`Zaczynasz od zera? Krok po kroku nauczymy cię kąpieli, suszenia i podstaw strzyżenia. Pracujesz na prawdziwych psach pod okiem instruktora, w małych grupach.`,buttonText:`Zobacz kursy`,secondButtonAnchor:``,helpMessage:`kursy`,imageUrl:`https://picsum.photos/id/1020/1920/1080`},{title:`Doświadczeni instruktorzy.`,additionText:`Nasza kadra robi kursy od 10 lat.`,param:`Uczą cię groomerzy z wieloletnią praktyką w salonach i na wystawach. Dzielą się sprawdzonymi technikami i trikami, których nie znajdziesz w podręcznikach.`,buttonText:`Poznaj zespół`,secondButtonAnchor:``,helpMessage:`instruktorzy`,imageUrl:`https://picsum.photos/id/1022/1920/1080`},{title:`Certyfikat na start kariery.`,additionText:`Potrzebujes dwujęzycznego? Nie ma problemu!`,param:`Każdy kurs kończy się egzaminem praktycznym i certyfikatem. Pomagamy też w pierwszych krokach zawodowych — od wyposażenia stanowiska po pozyskanie klientów.`,buttonText:`Dowiedz się więcej`,secondButtonAnchor:``,helpMessage:`certyfikat`,imageUrl:`https://picsum.photos/id/1023/1920/1080`},{title:`Zapisy na nowy semestr.`,additionText:`Dawaaaaj co ci szkodzi`,param:`Ruszają zapisy na kolejne edycje kursów. Liczba miejsc w grupach jest ograniczona, więc nie zwlekaj — zarezerwuj termin, który ci pasuje.`,buttonText:`Zarezerwuj miejsce`,secondButtonAnchor:``,helpMessage:`zapisy`,imageUrl:`https://picsum.photos/id/1025/1920/1080`}],t=`welcome-panel:leave`,n=`welcome-panel:enter`,r=(e,t)=>{document.dispatchEvent(new CustomEvent(e,{detail:{index:t}}))};export{e as i,t as n,r,n as t};